"""Deterministic market scenarios owned and generated by DevSoul."""

from decimal import ROUND_HALF_EVEN, Context, Decimal, localcontext
from random import Random

from devsoul_quant.domain.replay import Tick


class InvalidSyntheticScenario(ValueError):
    """Raised when a synthetic scenario configuration is invalid."""


def _required_precision(start_quote: Decimal, count: int) -> int:
    """Cover the quote magnitude, four-decimal steps, and cumulative carry."""
    exponent_distance = abs(start_quote.adjusted() - (-4))
    return max(28, len(start_quote.as_tuple().digits) + exponent_distance + len(str(count)) + 4)


def generate_ticks(
    *,
    seed: int,
    count: int,
    start_epoch: int = 1_700_000_000,
    start_quote: Decimal = Decimal("100.0000"),
    interval: int = 1,
) -> tuple[Tick, ...]:
    """Generate a deterministic random walk without provider data."""
    if type(seed) is not int:
        raise InvalidSyntheticScenario("seed must be an integer")
    if type(count) is not int or count < 2:
        raise InvalidSyntheticScenario("count must be an integer of at least two")
    if type(start_epoch) is not int:
        raise InvalidSyntheticScenario("start_epoch must be an integer")
    if type(interval) is not int or interval < 1:
        raise InvalidSyntheticScenario("interval must be a positive integer")
    if not isinstance(start_quote, Decimal) or not start_quote.is_finite() or start_quote <= 0:
        raise InvalidSyntheticScenario("start_quote must be a positive finite Decimal")

    decimal_context = Context(
        prec=_required_precision(start_quote, count),
        rounding=ROUND_HALF_EVEN,
    )
    random = Random(seed)
    with localcontext(decimal_context):
        quote = start_quote
        ticks = [Tick(epoch=start_epoch, quote=quote)]
        for offset in range(1, count):
            step = Decimal(random.randrange(-20, 21)) / Decimal("10000")
            quote += step
            if quote <= 0:
                raise InvalidSyntheticScenario("generated quote must remain positive")
            ticks.append(Tick(epoch=start_epoch + offset * interval, quote=quote))
    return tuple(ticks)
